mapper.select:
SELECT
dr.systematic_receipt, dr.product_id, dr.warehousing_id, dr.retrieval_id, dr.supplier_id, dr.customer_id,
dr.current_inventory, dr.actual_inventory, dr.plan_quantity, dr.univalence, dr.discount, dr.money, dr.cost,
dr.remarks, dr.product_specifications, dr.measure_unit, dr.locked_goods, dr.lock_inventory_qty,
(SELECT w1.warehouse_id FROM warehouse w1 WHERE w1.warehouse_id = dr.warehousing_id) AS warehousing_id,
(SELECT w1.warehouse_name FROM warehouse w1 WHERE w1.warehouse_id = dr.warehousing_id) AS warehousing_name,
(SELECT w2.warehouse_id FROM warehouse w2 WHERE w2.warehouse_id = dr.retrieval_id) AS retrieval_id,
(SELECT w2.warehouse_name FROM warehouse w2 WHERE w2.warehouse_id = dr.retrieval_id) AS retrieval_name,
p.product_id, p.product_code, p.product_name, p.product_type, p.producer,
pt.product_type_id, pt.parent_id, pt.ancestors, pt.product_type_name
FROM head_receipt hr
JOIN detail_receipt dr ON hr.systematic_receipt = dr.systematic_receipt
JOIN product p ON dr.product_id = p.product_id
JOIN product_type pt ON pt.product_type_id = p.product_type
WHERE 1=1

    AND hr.systematic_receipt like concat('%', #{systematicReceipt}, '%')


    AND hr.original_receipt like concat('%', #{originalReceipt}, '%')


    AND hr.receipt_category = #{receiptCategory}


    AND hr.receipt_type = #{receiptType}


    AND hr.receipt_status = #{receiptStatus}


    AND hr.warehousing_ids = #{warehousingIds}


    AND hr.retrieval_ids = #{retrievalIds}


    AND hr.user_ids = #{userIds}


    AND hr.supplier_ids = #{supplierIds}


    AND hr.customer_ids = #{customerIds}


    AND p.product_code like concat('%', #{productCode}, '%')


    AND p.product_name like concat('%', #{productName}, '%')


    AND dr.locked_goods = #{lockedGoods}


    AND date_format(hr.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


    AND date_format(hr.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')

SELECT dr.product_id, dr.plan_quantity, dr.univalence, dr.money, hr.receipt_type, p.product_code, p.product_name, p.product_type, p.product_specifications, p.measure_unit, pt.product_type_name, hr.systematic_receipt, hr.original_receipt, hr.invoice_date, hr.create_time, (SELECT su.user_name FROM sys_user su WHERE hr.user_ids = su.user_id) AS user_name, (SELECT s.supplier_name FROM supplier s WHERE hr.supplier_ids = s.supplier_id) AS supplier_name, (SELECT c.customer_name FROM customer c WHERE hr.customer_ids = c.customer_id) AS customer_name from detail_receipt dr JOIN head_receipt hr ON hr.systematic_receipt = dr.systematic_receipt JOIN product p ON dr.product_id = p.product_id JOIN product_type pt ON pt.product_type_id = p.product_type WHERE hr.receipt_status = 2
AND date_format(hr.invoice_date,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')
AND date_format(hr.invoice_date,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')
AND hr.systematic_receipt like concat('%', #{systematicReceipt}, '%')
AND dr.warehousing_id = #{warehousingId}
AND dr.retrieval_id = #{retrievalId}
AND p.product_code like concat('%', #{productCode}, '%')
AND p.product_name like concat('%', #{productName}, '%')
AND hr.user_ids = #{userIds}
AND hr.supplier_ids = #{supplierIds}
AND hr.customer_ids = #{customerIds}
